5) Revisão diária enquanto durar o pico.',null,null,'{"number":11,"code":"SAFRA-11","name":"Pico de volume acima da capacidade","trigger":"Volume de pedidos/dia acima do limiar planejado para a Safra.","activation":"Automático — volume diário cruza o limiar do plano (Painel/PCP).","protocol":"1) Painel sinaliza volume acima do planejado.\n2) PCP + Operação acionam o plano de pico (turnos/posições/parceiros).\n3) Adequação de SLA B2C para aliviar o CD (prazos inteligentes).\n4) Consolidação de carga reforçada.\n5) Revisão diária enquanto durar o pico.","responsible_area":"Logística","owner":"Daniel Garcia","impacted_areas":"PCP, Comercial","sla_target":"Plano de pico acionado no dia;\nsem turnos extras não planejados","tool":"Painel de Protocolos (BI) + Cockpit","monitoring_visibility":"Volume diário × capacidade no Painel; gargalos por etapa.","validation_participants":"Daniel, Renato","mapping":"EDB06","source_row":55,"source_file":"EDB06 - Matriz Contingencia v3.xlsx","source_sheet":"Matriz de Contingência","source_sha256":"b0cca8cce835dbdc65ab0c30212fd89480d2cf51e9fb62d215ad1bde0963ead6"}' from public.scenarios sc where sc.code='SAFRA-11' and not exists (select 1 from public.scenario_versions sv where sv.scenario_id=sc.id and sv.version_no=1);


update public.scenario_versions sv set status='PUBLISHED' from public.scenarios sc where sv.scenario_id=sc.id and sv.version_no=1 and sv.status='DRAFT' and sc.code ~ '^SAFRA-(0[1-9]|1[01])$';
update public.scenarios sc set current_version_id=sv.id from public.scenario_versions sv where sv.scenario_id=sc.id and sv.version_no=1 and sv.status='PUBLISHED' and sc.code ~ '^SAFRA-(0[1-9]|1[01])$';

do $$ declare v_s integer; v_v integer; v_o integer; v_nullcrit integer; begin
 select count(*) into v_s from public.scenarios where code ~ '^SAFRA-(0[1-9]|1[01])$';
 select count(*) into v_v from public.scenario_versions sv join public.scenarios sc on sc.id=sv.scenario_id where sc.code ~ '^SAFRA-(0[1-9]|1[01])$' and sv.version_no=1 and sv.status='PUBLISHED';
 select count(*) into v_o from public.scenario_owners so join public.scenarios sc on sc.id=so.scenario_id where sc.code ~ '^SAFRA-(0[1-9]|1[01])$' and so.valid_to is null;
 select count(*) into v_nullcrit from public.scenario_versions sv join public.scenarios sc on sc.id=sv.scenario_id where sc.code ~ '^SAFRA-(0[1-9]|1[01])$' and sv.version_no=1 and sv.criticality is null;
 if v_s<>11 or v_v<>11 or v_o<>11 or v_nullcrit<>11 then raise exception 'C06 seed invariant failed: scenarios %, versions %, owners %, nullcrit %',v_s,v_v,v_o,v_nullcrit; end if;
end $$;
commit;
