insert into public.scenario_version_systems(scenario_version_id,system_id,context) select sv.id,sy.id,'Ferramenta canônica da Matriz v3' from public.scenarios sc join public.scenario_versions sv on sv.scenario_id=sc.id and sv.version_no=1 join public.systems sy on sy.name='Painel de Protocolos (BI) + Cockpit' where sc.code='SAFRA-11' on conflict do nothing;
